        return -1 if v < 0 else (1 if v > 0 else 0)

    def is_num(x):
        return isinstance(x, (int, float))

    def get_pos(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            for keys in (("x", "y"), ("col", "row"), ("cx", "cy")):
                if keys[0] in obj and keys[1] in obj and is_num(obj.get(keys[0])) and is_num(obj.get(keys[1])):
                    return [obj.get(keys[0]), obj.get(keys[1])]
            for k in ("pos", "position", "loc", "location"):
                p = obj.get(k)
                if isinstance(p, (list, tuple)) and len(p) >= 2 and is_num(p[0]) and is_num(p[1]):
                    return [p[0], p[1]]
        if isinstance(obj, (list, tuple)):
            if len(obj) >= 2 and is_num(obj[0]) and is_num(obj[1]):
                return [obj[0], obj[1]]
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def iter_positions(v):
        if v is None:
            return
        if isinstance(v, dict):
            if "x" in v and "y" in v and is_num(v.get("x")) and is_num(v.get("y")):
                yield [v.get("x"), v.get("y")]
                return
            p = get_pos(v)
            if p is not None:
                yield p
                return
            for vv in v.values():
                for p2 in iter_positions(vv):
                    yield p2
        elif isinstance(v, (list, tuple)):
            if len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
                yield [v[0], v[1]]
            else:
                for item in v:
                    for p2 in iter_positions(item):
